#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int da_dung[5] = {0};
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        da_dung[x] = 1;
    }
    int dem = 0;
    for (int k = 1; k <= 4; k++) dem += da_dung[k];
    printf("%d\n", dem);
    return 0;
}
